import fs, { type FileRef } from "@rcompat/fs";
import { instructionsSchema, type Instructions } from "#schemas/instruction";
import { validateOutputTree } from "#utils/validate-output";

/**
 * Full output validation: schema conformance, template file existence,
 * variable ordering, step name uniqueness, and suboutput tree integrity.
 * Returns a list of issue strings (empty = valid). Never throws on a
 * validation failure.
 */
export async function checkOutput(args: {
  rootOutputDir: FileRef;
  currentOutputDir: FileRef;
}): Promise<string[]> {
  const { rootOutputDir, currentOutputDir } = args;
  const outputPath = currentOutputDir.append("/instructions.json");
  const issues: string[] = [];

  if (!(await fs.exists(outputPath))) {
    return ["instructions.json not found"];
  }

  let instructions: Instructions;
  try {
    instructions = instructionsSchema.parse(await outputPath.json());
  } catch (error_) {
    issues.push(error_ instanceof Error ? error_.message : String(error_));
    return issues;
  }

  // Validate variable declarations
  const required = instructions.variables.required;
  const optional = instructions.variables.optional ?? [];

  // a) Required/optional name collision
  for (const opt of optional) {
    const collision = required.some(r => r.toLowerCase() === opt.toLowerCase());
    if (collision) {
      issues.push(`variable "${opt}" is declared as both required and optional`);
    }
  }

  // b) Optional variable used in an output path
  const pathVariables = new Set<string>();
  for (const step of instructions.steps) {
    if (step.type === "create" || step.type === "modify" || step.type === "delete") {
      for (const [, token] of step.outputPath.matchAll(/\{\{(\w+)\}\}/g)) {
        pathVariables.add(token);
      }
    }
  }
  for (const pathVar of pathVariables) {
    const isOptionalVar = optional.some(
      v => v.toLowerCase() === pathVar.toLowerCase(),
    );
    if (isOptionalVar) {
      issues.push(
        `variable "${pathVar}" is used in an output path but declared optional; it should be required`,
      );
    }
  }

  // c) Template file existence for create, modify, and read (template mode)
  for (const step of instructions.steps) {
    if (step.type === "create" || step.type === "modify") {
      const templatePath = currentOutputDir.append(`/${step.template}`);
      if (!(await fs.exists(templatePath))) {
        issues.push(`missing template file: ${step.template}`);
      }
    }
    if (step.type === "read" && step.template) {
      const templatePath = currentOutputDir.append(`/${step.template}`);
      if (!(await fs.exists(templatePath))) {
        issues.push(`missing template file: ${step.template}`);
      }
    }
  }

  // d) Step name uniqueness
  const seenNames = new Set<string>();
  for (const step of instructions.steps) {
    if (seenNames.has(step.name)) {
      issues.push(`duplicate step name: ${step.name}`);
    }
    seenNames.add(step.name);
  }

  // e) Variable ordering validation
  const available = new Set<string>([
    ...required.map(r => r.toLowerCase()),
    ...optional.map(o => o.toLowerCase()),
  ]);

  for (const step of instructions.steps) {
    const tokens = new Set<string>();

    if (step.type === "create" || step.type === "modify" || step.type === "delete") {
      for (const [, token] of step.outputPath.matchAll(/\{\{(\w+)\}\}/g)) {
        tokens.add(token.toLowerCase());
      }
    } else if (step.type === "read") {
      for (const [, token] of step.path.matchAll(/\{\{(\w+)\}\}/g)) {
        tokens.add(token.toLowerCase());
      }
    } else if (step.type === "include") {
      for (const value of Object.values(step.variables)) {
        for (const [, token] of value.matchAll(/\{\{(\w+)\}\}/g)) {
          tokens.add(token.toLowerCase());
        }
      }
    }

    for (const token of tokens) {
      if (!available.has(token)) {
        issues.push(`step "${step.name}" uses {{${token}}} before it is available`);
      }
    }

    if (step.type === "read") {
      available.add(step.as.toLowerCase());
    }
  }

  // f) Read `as` collision with declared variables
  for (const step of instructions.steps) {
    if (step.type === "read") {
      const allDeclared = [...required, ...optional];
      if (allDeclared.some(v => v.toLowerCase() === step.as.toLowerCase())) {
        issues.push(`read step "${step.name}" produces variable "${step.as}" which shadows a declared variable`);
      }
    }
  }

  // Validate suboutput tree
  const treeIssues = await validateOutputTree({
    rootOutputDir,
    currentOutputDir,
  });
  issues.push(...treeIssues);

  return issues;
}

import fs, { type FileRef } from "@rcompat/fs";
import { instructionsSchema, type Instructions } from "#schemas/instruction";
import is from "@rcompat/is";

/**
 * Validate the suboutput tree of a output. Walks all include steps recursively,
 * checking: existence, circular references, variable mapping completeness,
 * parentVar reference validity, stepOverride name validity, and excludeSteps
 * name validity.
 *
 * Returns a list of issue strings (empty = valid). Does not throw.
 */
export async function validateOutputTree(args: {
  rootOutputDir: FileRef;
  currentOutputDir: FileRef;
  pathStack?: string[];
}): Promise<string[]> {
  const { rootOutputDir, currentOutputDir } = args;
  const currentName = currentOutputDir.name;
  const pathStack = [...(args.pathStack ?? []), currentName];
  const issues: string[] = [];

  const outputPath = currentOutputDir.append("/instructions.json");

  if (!(await fs.exists(outputPath))) {
    return ["instructions.json not found"];
  }

  let instructions: Instructions;
  try {
    instructions = instructionsSchema.parse(await outputPath.json());
  } catch {
    return [`instructions.json parse failed: ${currentOutputDir.name}`];
  }

  // Collect all available variable names in this scope (declared + read-produced)
  const allParentVariables = [
    ...instructions.variables.required,
    ...(instructions.variables.optional ?? []),
  ];
  for (const step of instructions.steps) {
    if (step.type === "read") {
      allParentVariables.push(step.as);
    }
  }

  for (const step of instructions.steps) {
    if (step.type !== "include") continue;

    // a. Existence
    const suboutputDir = rootOutputDir.append(`/${step.name}`);
    if (!(await fs.exists(suboutputDir))) {
      issues.push(`suboutput not found: ${step.name}`);
      continue;
    }

    // b. Cycle
    if (pathStack.includes(step.name)) {
      const chain = [...pathStack, step.name];
      issues.push(`circular reference: ${chain.join(" → ")}`);
      continue;
    }

    // c. Load suboutput instructions
    const subOutputPath = suboutputDir.append("/instructions.json");
    let subInstructions: Instructions;
    try {
      subInstructions = instructionsSchema.parse(await subOutputPath.json());
    } catch {
      issues.push(`instructions.json parse failed: ${step.name}`);
      continue;
    }

    // Every declared variable (required + optional) must have a mapping key
    const subAllVariables = [
      ...subInstructions.variables.required,
      ...(subInstructions.variables.optional ?? []),
    ];
    for (const declared of subAllVariables) {
      const mapped = Object.keys(step.variables).find(
        k => k.toLowerCase() === declared.toLowerCase(),
      );

      if (is.falsy(mapped)) {
        issues.push(`unmapped variable: ${declared} in suboutput: ${step.name}`);
      }
    }

    // {{parentVar}} tokens must refer to parent's available variables
    for (const value of Object.values(step.variables)) {
      const tokens = value.match(/\{\{(\w+)\}\}/g) ?? [];
      for (const token of tokens) {
        const varName = token.slice(2, -2);
        const declared = allParentVariables.find(
          v => v.toLowerCase() === varName.toLowerCase(),
        );

        if (is.falsy(declared)) {
          issues.push(`invalid reference: {{${varName}}} in suboutput: ${step.name}`);
        }
      }
    }

    // Collect child step names for override/exclude validation
    const childStepNames = new Set(subInstructions.steps.map(s => s.name));

    // d. stepOverride keys must match child step names
    if (is.defined(step.stepOverride)) {
      for (const overrideKey of Object.keys(step.stepOverride)) {
        if (!childStepNames.has(overrideKey)) {
          issues.push(`override file not found: ${overrideKey} in suboutput: ${step.name}`);
        }
      }
    }

    // e. excludeSteps names must match child step names
    if (is.defined(step.excludeSteps)) {
      for (const excluded of step.excludeSteps) {
        if (!childStepNames.has(excluded)) {
          issues.push(`exclude file not found: ${excluded} in suboutput: ${step.name}`);
        }
      }
    }

    // f. stepOverride/excludeSteps conflict: same name in both
    const overrideNames = new Set(Object.keys(step.stepOverride ?? {}));
    const excludeNames = new Set(step.excludeSteps ?? []);
    for (const name of overrideNames) {
      if (excludeNames.has(name)) {
        issues.push(`conflict: "${name}" in both excludeSteps and stepOverride for suboutput: ${step.name}`);
      }
    }

    // g. Recurse
    const childIssues = await validateOutputTree({
      rootOutputDir,
      currentOutputDir: suboutputDir,
      pathStack,
    });
    issues.push(...childIssues);
  }

  return issues;
}

import test from "@rcompat/test";
import fs, { type FileRef } from "@rcompat/fs";
import runtime from "@rcompat/runtime";
import { checkOutput } from "#utils/check-output";
import { MAIN_FOLDER, ACTIVE_FOLDER, MULTI_USE_FOLDER } from "#constants";

const root = await runtime.projectRoot();
const testRoot: FileRef = root.append("/tmp");
const mainFolder: FileRef = testRoot.append(`/${MAIN_FOLDER}`);
const multiUseFolder: FileRef = mainFolder.append(`/${ACTIVE_FOLDER}/${MULTI_USE_FOLDER}`);

async function reset() {
  await testRoot.remove();
  await fs.create(testRoot);
  await fs.create(mainFolder);
  await fs.create(multiUseFolder);
}

async function writeOutput(name: string, instructions: Record<string, unknown>) {
  const dir = multiUseFolder.append(`/${name}`);
  await fs.create(dir);
  await dir.append("/instructions.json").writeJSON(instructions as never);
}

test.case("should return no issues for valid output with no includes", async assert => {
  await reset();
  await writeOutput("simple", {
    name: "simple",
    description: "test description",
    variables: { required: ["ComponentName"] },
    intent: [],
    steps: [],
  });

  const issues = await checkOutput({
    rootOutputDir: multiUseFolder,
    currentOutputDir: multiUseFolder.append("/simple"),
  });

  assert(issues.length).equals(0);
  await testRoot.remove();
});

test.case("should return an issue for missing instructions.json", async assert => {
